    표2_역사적배경: [
        {"항목":"아라 가문", "내용":"아라(나그네/여행자)라는 이름은 아브라함 이래 이스라엘의 정체성인 나그네 됨을 반영한다. 이 나그네의 가문이 고향으로 돌아온 것은 의미심장하다", "목회적활용":"이 땅에서의 나그네 된 삶이 결국 영원한 고향을 향한 여정임을 가르칩니다"},
        {"항목":"775명", "내용":"느헤미야 7:10에서는 652명으로 기록되어 차이가 있다. 이는 등록 시점의 차이나 가문 경계의 차이로 설명된다", "목회적활용":"성경의 숫자 차이에 대해 겸손하게 접근하면서 핵심 메시지에 집중하도록 안내합니다"},
        {"항목":"나그네의 귀환", "내용":"아라(나그네)라는 이름의 가문이 바벨론 포로에서 귀환한 것은 이중적 나그네 됨의 종료를 의미한다. 이 땅의 나그네가 약속의 땅으로 돌아왔다", "목회적활용":"우리도 이 세상의 나그네로서 영원한 본향을 향해 나아가는 존재임을 기억하게 합니다"}
    ],
    표3_신학적의미: [
        {"교리":"나그네 신학", "설명":"아라(나그네) 가문의 귀환은 이 땅에서의 나그네 된 삶이 영원한 고향을 향한 여정임을 보여준다", "관련구절":"히브리서 11:13-16, 창세기 47:9, 베드로전서 2:11"},
        {"교리":"약속의 땅 회복", "설명":"나그네의 가문이 약속의 땅으로 돌아온 것은 하나님이 자기 백성에게 약속하신 안식처를 회복시키심을 보여준다", "관련구절":"시편 23:6, 요한복음 14:2-3, 히브리서 4:9"},
        {"교리":"정확한 기록의 신학", "설명":"775명이라는 정확한 수는 나그네의 삶 속에서도 하나님이 정확히 세시고 기억하심을 증거한다", "관련구절":"시편 56:8, 시편 139:16, 말라기 3:16"}
    ],
    표4_예표론: [
        {"구분":"나그네 가문의 귀향과 성도의 영원한 귀향", "내용":"나그네라는 이름의 가문이 고향으로 돌아온 것은 진정한 귀향의 상징이다", "그리스도연결":"우리도 이 세상의 나그네로서 하늘 본향을 향해 나아가며 종국에는 영원한 귀향을 맞이한다(히브리서 11:13-16)"},
        {"구분":"포로에서의 해방과 죄에서의 자유", "내용":"바벨론에서 예루살렘으로의 귀환은 속박에서 자유로의 전환이다", "그리스도연결":"그리스도 안에서 우리는 죄의 속박에서 해방되어 영적 자유를 누린다(요한복음 8:36)"},
        {"구분":"중간 규모 가문의 기록과 모든 자의 구원", "내용":"775명의 중간 크기 가문도 동등하게 기록되었다", "그리스도연결":"하나님의 구원은 크고 작은 자를 차별하지 않으신다(사도행전 10:34-35)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"The children of Arah, seven hundred seventy and five. Arah means 'a wayfarer.' The wanderers have come home.", "한국어번역":"아라의 자손이 775명이다. 아라는 '나그네'라는 뜻이다. 방랑자들이 집으로 돌아왔다.", "핵심통찰":"나그네들이 드디어 집으로 돌아왔다"},
        {"영어원문":"God brings his wandering children home. None are too far gone for his grace to reach.", "한국어번역":"하나님은 방황하는 자녀들을 집으로 데려오신다. 하나님의 은혜가 미치지 못할 만큼 멀리 간 자는 없다.", "핵심통찰":"하나님의 은혜가 닿지 못할 곳은 없다"},
        {"영어원문":"Every family is precious to God, regardless of size. He numbers them all and calls them by name.", "한국어번역":"모든 가문이 크기와 상관없이 하나님께 소중하다. 그가 모두를 세시고 이름으로 부르신다.", "핵심통찰":"크기와 상관없이 모든 가문이 하나님께 소중하다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"나그네의 귀향 - 방랑이 끝나는 곳", "예화_적용":"에스라 2:5의 아라(나그네) 가문 귀환을 중심으로"},
        {"대지":"서론", "내용":"아라, 나그네라는 이름입니다. 이 나그네의 가문이 드디어 고향으로 돌아왔습니다. 모든 방랑에는 끝이 있습니다.", "예화_적용":"오디세우스의 20년 방랑이 결국 고향 이타카로 끝났듯이 우리의 영적 방랑도 끝이 있습니다"},
        {"대지":"1대지: 나그네의 이름 (이 땅의 삶의 본질)", "내용":"아라(나그네)라는 이름은 이 땅에서의 삶이 본질적으로 순례임을 보여준다", "예화_적용":"우리도 이 땅에서 영원한 본향을 향해 걸어가는 나그네입니다"},
        {"대지":"2대지: 775명의 귀환 (함께 돌아옴)", "내용":"나그네의 가문이 혼자가 아닌 775명이 함께 돌아온 것은 공동체적 귀환의 모습이다", "예화_적용":"신앙의 여정은 혼자가 아닌 함께 걷는 것입니다"},
        {"대지":"3대지: 예루살렘으로 (영원한 본향)", "내용":"나그네의 최종 목적지는 예루살렘 하나님의 도성이다. 방랑이 아닌 귀향이 우리의 운명이다", "예화_적용":"요한계시록의 새 예루살렘이 우리의 최종 목적지임을 기억하며 소망합시다"},
        {"대지":"결론", "내용":"나그네의 여정이 끝나는 곳은 하나님의 집입니다. 아직 방랑 중인 당신에게도 귀향의 날이 올 것입니다.", "예화_적용":"탕자가 아버지의 집으로 돌아온 것처럼 하나님은 우리의 귀환을 기다리고 계십니다"}
    ],
